// Block (composition) — dropped and uploaded files with progress and removal actions.
// DropZone, ProgressBar, and Button own their look; Stack owns arrangement.
import type { ReactNode, Ref } from "react";
import { Button } from "../components/Button";
import { DropZone } from "../components/DropZone";
import { ProgressBar } from "../components/ProgressBar";
import { Stack } from "../layouts/Stack";
import "./FileList.css";

export interface FileListProps {
  /** Files to display. */
  files: {
    id: string;
    name: string;
    size?: string;
    progress?: number;
  }[];
  onRemove?: (id: string) => void;
  onDrop?: (files: File[]) => void;
  showDropZone?: boolean;
  /** Message shown when there are no files. */
  emptyLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function FileList({
  files,
  onRemove,
  onDrop,
  showDropZone,
  emptyLabel = "No files yet",
  className,
  ref,
}: FileListProps) {
  const handleDrop = onDrop
    ? (event: Parameters<NonNullable<React.ComponentProps<typeof DropZone>["onDrop"]>>[0]) => {
        const droppedFiles = event.items
          .filter((item) => item.kind === "file")
          .map((item) => item.getFile());
        void Promise.all(droppedFiles).then(onDrop);
      }
    : undefined;

  // Under the DropZone the file names share its start edge, so the name and size take the inset
  // (component-contract.md §6 rule 8); the row's progress bar and Button stay on the box line. Without
  // the DropZone no box stands in that column and the names stay at 0.
  const hasDropZone = Boolean(showDropZone || onDrop);
  const text = (className: string, children: ReactNode) =>
    hasDropZone ? (
      <>
        <span className={className}>{children}</span>
      </>
    ) : (
      <span className={className}>{children}</span>
    );

  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      aria-label="Files"
      className={className ? `sd-filelist ${className}` : "sd-filelist"}
    >
      {hasDropZone && (
        <DropZone aria-label="Upload files" onDrop={handleDrop}>
          <span className="sd-filelist__drop-label sd-type-label-medium">
            Drop files here to upload
          </span>
        </DropZone>
      )}
      {files.length === 0 ? (
        <p role="status" className="sd-filelist__empty sd-type-caption-medium">
          {emptyLabel}
        </p>
      ) : (
        <Stack as="ul" gap="small" className="sd-filelist__items">
          {files.map((file) => (
            <Stack
              as="li"
              key={file.id}
              direction="row"
              align="center"
              justify="between"
              gap="large"
              className="sd-filelist__item"
            >
              <Stack gap="2x-small" className="sd-filelist__details">
                {text("sd-filelist__name sd-type-body-medium", file.name)}
                {file.size && text("sd-filelist__size sd-type-caption-medium", file.size)}
              </Stack>
              {(file.progress != null || onRemove) && (
                <Stack direction="row" align="center" gap="small" className="sd-filelist__actions">
                  {file.progress != null && (
                    <ProgressBar
                      value={file.progress}
                      aria-label={`Upload progress for ${file.name}`}
                      className="sd-filelist__progress"
                    />
                  )}
                  {onRemove && (
                    <Button
                      type="button"
                      variant="secondary"
                      size="small"
                      aria-label={`Remove ${file.name}`}
                      onPress={() => onRemove(file.id)}
                    >
                      Remove
                    </Button>
                  )}
                </Stack>
              )}
            </Stack>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

/* FileList.css — .sd-filelist (Block)
   Arrangement only: composed Components retain complete ownership of their look. */
.sd-filelist {
  width: 100%;
}

.sd-filelist__items {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The name keeps a readable column and the progress bar gives way first: at 360 a fixed-width
   bar would leave the name ~49px and break a file name letter by letter. */
.sd-filelist__details {
  flex: 1 0 7rem;
  min-width: 0;
}

.sd-filelist__name {
  overflow-wrap: anywhere;
}

.sd-filelist__actions {
  flex: 0 1 auto;
  min-width: 0;
}

.sd-filelist__progress {
  flex: 0 1 8rem;
  min-width: 3rem;
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-filelist__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
